118:   const child={id:cryptoId(),name:makeName(genome,[parent,mate]),genome,sex:sexOf(),needs:freshNeeds(90),wins:0,battles:0,born:Date.now(),generation:Math.max(parent.generation||0,mate.generation||0)+1,parents:[parent.id,mate.id]}
119:   game.creatures.push(child); game.selected=child.id; closeModal(); if(mode==='habitat') { world.addCreature(child,{position:[0,0,0]}); world.setSelected(child.id) }
120:   persist(); renderRoster(); renderProfile(); toast(`${child.name} hatched with ${mutations.length} mutated gene${mutations.length===1?'':'s'}!`)
