126: function rename() { const input=$('#rename-input'), name=input?.value.trim(); if(!name)return toast('A name cannot be empty.'); selected().name=name; closeModal(); renderRoster(); renderProfile(); persist(); toast('Specimen renamed.') }
127: function arenaDialog() {
