154:   hud.innerHTML=`${bar('player','YOUR CREATURE')}<div class="battle-turn">ROUND ${battle.turn}<small>${battle.busy?'ACTION IN PROGRESS':'CHOOSE AN ABILITY'}</small></div>${bar('foe','OPPONENT')}`
155:   if(battle.finished) { result.classList.remove('hidden'); result.innerHTML=`<div class="result-stamp">${battle.winner==='player'?'VICTORY':'DEFEAT'}</div><b>${esc(battle.winner==='player'?battle.player.name:battle.foe.name)} ${battle.winner==='player'?'wins the bout':'takes the round'}</b><button class="primary-btn" data-action="battle-exit">RETURN TO HOLLOW</button>` } else result.classList.add('hidden')
156:   renderProfile()
